mapper.select:
SELECT * FROM shopwizard.tAdjAdjust
WHERE AdjustStartDate >= DATE_FORMAT(#{pAdjustStartDate}, '%Y%m%d') AND AdjustStartDate < ADDDATE(DATE_FORMAT(#{pAdjustEndDate}, '%Y%m%d'), INTERVAL 1 DAY)
AND AdjustEndDate >= DATE_FORMAT(#{pAdjustStartDate}, '%Y%m%d') AND AdjustEndDate < ADDDATE(DATE_FORMAT(#{pAdjustEndDate}, '%Y%m%d'), INTERVAL 1 DAY)
AND AdjustNo = #{pAdjustNo}
LIMIT ${pPageOffset}, ${pPageSize}

SELECT COUNT(*) FROM shopwizard.tAdjAdjust A
INNER JOIN shopwizard.tCmpShop S ON A.ShopCode = S.ShopCode
WHERE A.AdjustStartDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND A.AdjustEndDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY)
AND A.ShopCode = #{pShopCode}
AND S.adjustPeriodCode = #{pAdjustPeriodType}
